class Solution {
public:
    bool checkPossibility(vector<int>& nums) {
        int n=nums.size();
        int cnt=0;
        for(int i=1;i<n;i++)
        {
            if(nums[i-1]>nums[i])
            {
                cnt+=1;
                if(i-2<0 or nums[i-2]<=nums[i])
                    nums[i-1]=nums[i];
                else
                    nums[i]=nums[i-1];
            }
        }
        return cnt<=1;
    }
};

class Solution(object):
    def checkPossibility(self, nums):
        """
        :type nums: List[int]
        :rtype: bool
        """
        flag = False
        p = 0
        while p < len(nums) - 1:
            if nums[p] > nums[p + 1]:
                if flag:
                    return False
                if p == 0 or p == len(nums) - 2:
                    flag = True
                    p += 1
                elif nums[p - 1] <= nums[p + 1]:
                    flag = True
                    p += 1
                elif nums[p] <= nums[p + 2]:
                    flag = True
                    p += 2
                else:
                    return False
            else:
                p += 1
        return True
